/**
 * Build-time generator for `src/renderer/src/word/templateBytes.ts`.
 *
 * Why this exists
 * ---------------
 * The Word export uses `Molio 2_Skabelon BDB.docx` as a styling
 * template — we unzip it, replace the body content with BDB data,
 * then repack. The renderer needs the template's bytes at runtime,
 * and the simplest way to ship them is a pre-built TypeScript module
 * with the bytes as a base64 string. Same trick as the Open Sans
 * VFS (see `build-open-sans-vfs.mjs`).
 *
 * Run when
 * --------
 *   - First app setup (the generated file is committed to source so
 *     `npm run dev` works without running this first).
 *   - Whenever the template file at the source path below is
 *     updated by Tore.
 *
 * Usage
 * -----
 *   node packages/app/scripts/build-bdb-template.mjs
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PACKAGE_ROOT = resolve(__dirname, "..");
const REPO_ROOT = resolve(PACKAGE_ROOT, "..", "..");

const TEMPLATE_PATH = join(
  REPO_ROOT,
  "0900 Examples",
  "Basics + Work_areas",
  "Molio 2_Skabelon BDB.docx",
);
const OUT_PATH = join(
  PACKAGE_ROOT,
  "src",
  "renderer",
  "src",
  "word",
  "templateBytes.ts",
);

console.log("Reading template from", TEMPLATE_PATH);
const bytes = readFileSync(TEMPLATE_PATH);
const b64 = bytes.toString("base64");
console.log(
  `Template size: ${bytes.length} bytes (${b64.length} base64 chars)`,
);

const out = `/**
 * BDB Word-export template bytes — generated by
 * \`scripts/build-bdb-template.mjs\`.
 *
 * The template is \`0900 Examples/Basics + Work_areas/Molio 2_Skabelon BDB.docx\`.
 * We base64-bundle it here so the renderer can read it synchronously
 * at export time without an async file fetch. The bytes are
 * decoded once at module load.
 *
 * Regenerate by running
 *   \`node packages/app/scripts/build-bdb-template.mjs\`
 * from the repo root after Tore updates the template file.
 */

/* eslint-disable */

const BASE64 = "${b64}";

/**
 * Decode the base64 template once at module load and cache the
 * resulting bytes. Returns a fresh Uint8Array on each call so
 * downstream code can mutate freely without affecting the cache.
 */
let cached: Uint8Array | null = null;

export function getBdbTemplateBytes(): Uint8Array {
  if (cached == null) {
    // Browser-side: \`atob\` returns a binary string we need to
    // convert byte-by-byte. Faster than fetch + arrayBuffer.
    const binStr = atob(BASE64);
    const out = new Uint8Array(binStr.length);
    for (let i = 0; i < binStr.length; i++) {
      out[i] = binStr.charCodeAt(i);
    }
    cached = out;
  }
  // Return a copy so callers can splice / repack without polluting
  // the shared cache. Copying 56 KB is negligible.
  return new Uint8Array(cached);
}
`;

writeFileSync(OUT_PATH, out);
console.log("Wrote", OUT_PATH);
